  assert.deepEqual(evaluate(flag, ctx("u", { a: 1, b: 3 })), { on: false, reason: "rollout" });
  assert.deepEqual(evaluate(flag, ctx("u", { a: 0, b: 2 })), { on: false, reason: "rollout" });
