test("evaluate: rule rollouts use the flag key and salt", () => {
  const flag: Flag = { key: "new-checkout", enabled: true, rules: [{ when: [cond("x", "eq", 1)], serve: { rollout: 30 } }], salt: "" };
  const run = (u: string) => evaluate(flag, ctx(u, { x: 1 }));
